<script setup lang="ts">import { useAttrs } from "vue"; defineOptions({ inheritAttrs: false }); defineProps<{ modelValue?: string; invalid?: boolean; describedby?: string; labelledby?: string }>(); const emit=defineEmits<{(event:"update:modelValue",value:string):void}>(); const attrs=useAttrs();</script>
<template><textarea v-bind="attrs" :value="modelValue" :aria-invalid="invalid || undefined" :aria-describedby="describedby" :aria-labelledby="labelledby" class="min-h-24 w-full rounded-sm border border-input bg-card px-3 py-2 text-sm outline-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/20 aria-invalid:border-destructive" @input="emit('update:modelValue',($event.target as HTMLTextAreaElement).value)" /></template>
